-- ------------------------------------------------------------------
-- Tabela: pacientes
-- ------------------------------------------------------------------
CREATE TABLE pacientes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(150) NOT NULL,
    cpf VARCHAR(20) NOT NULL,
    data_nascimento DATE,
    sexo CHAR(1),
    telefone VARCHAR(20),
    email VARCHAR(150),
    endereco VARCHAR(200),
    cidade VARCHAR(100),
    estado CHAR(2),
    tipo_sanguineo VARCHAR(3),
    convenio_id INT,
    data_cadastro DATE
);

