-- ------------------------------------------------------------------
-- Tabela: internacoes
-- ------------------------------------------------------------------
CREATE TABLE internacoes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    paciente_id INT NOT NULL,
    medico_id INT,
    hospital_id INT,
    data_entrada DATE,
    data_saida DATE,
    motivo VARCHAR(100),
    quarto VARCHAR(10),
    valor_diaria DECIMAL(8,2),
    status VARCHAR(20)
);

